package io.blueeye.core.decoders.parser.apple

import javax.inject.Inject
import javax.inject.Singleton

/**
 * Parser for Apple Find My / Offline Finding (Type 0x12). Based on OpenHaystack / Seemoo Lab
 * research.
 */
@Singleton
class FindMyParser
@Inject
constructor() {
    fun parse(data: ByteArray): AppleDeviceData? {
        if (data.size < 2) return null

        // Byte 0: Status
        val statusByte = data[0].toInt() and 0xFF

        // Maintained means an owner connection occurred in the current key period.
        // Battery bits 6-7 are meaningful only when maintained is set.
        // Bits 0-1 are reserved and must not be interpreted as low battery.
        val maintained = (statusByte and 0x04) != 0
        val batteryCode = (statusByte ushr 6) and 0x03
        val lowBattery = maintained && batteryCode >= 2

        // Public Key extraction
        // The payload (bytes 1..end) represents the truncated public key.
        // Usually 22-28 bytes depending on protocol version.
        val publicKey =
            if (data.size > 1) {
                data.copyOfRange(1, data.size)
            } else {
                null
            }

        var debugInfo = if (maintained) "Find My [Maintained]" else "Find My [Not Maintained]"
        if (lowBattery) {
            debugInfo += if (batteryCode == 3) " [Critical Batt]" else " [Low Batt]"
        }

        return AppleDeviceData(
            deviceModel = debugInfo,
            statusFlags = statusByte,
            findMyKey = publicKey,
        )
    }
}

package io.blueeye.core.decoders

import io.blueeye.core.model.SensorData
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class AirTagBroadcastDecoder
@Inject
constructor() : BleBeaconDecoder {
    override fun supports(input: BleBeaconScanInput): Boolean {
        val manufacturerId = input.manufacturerId
        val data = input.data
        // Apple ID = 76 (0x004C)
        if (manufacturerId != 76 || data == null || data.size < 2) return false

        // Type 0x12 = Find My
        return data[0] == 0x12.toByte()
    }

    override fun decode(input: BleBeaconScanInput): SensorData {
        val data = input.data ?: byteArrayOf()
        // Format: [12] [Len] [Status] [22 bytes Key Part] ...

        // Status Byte (index 2):
        // Bits 6-7: Battery Level (00=Full, 01=Medium, 10=Low, 11=Critical)
        // Bit 2: Maintained. Battery bits are valid only when this bit is set.

        var batteryStatus = "Unknown"
        var statusByte = 0

        if (data.size > 2) {
            statusByte = data[2].toInt() and 0xFF
            batteryStatus =
                if ((statusByte and 0x04) == 0) {
                    "Unknown"
                } else {
                    when ((statusByte shr 6) and 0x03) {
                        0x00 -> "Full"
                        0x01 -> "Medium"
                        0x02 -> "Low"
                        0x03 -> "Critical"
                        else -> "Unknown"
                    }
                }
        }

        // Public Key Part (22 bytes starting at offset 3)
        // This key part combined with MAC address forms the full tracking key.
        val publicParts =
            if (data.size >= 25) {
                data.copyOfRange(3, 25).joinToString("") { "%02X".format(it) }
            } else {
                "Partial Data"
            }

        return SensorData(
            sensorStatus = "Bat: $batteryStatus (St: 0x%02X)".format(statusByte),
            beaconType = "Apple FindMy / AirTag",
            rawData = "KeyPart: $publicParts",
        )
    }
}

package io.blueeye.core.decoders.parser.apple

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

class FindMyParserTest {
    private val parser = FindMyParser()

    @Test
    fun `reserved low bit is not a low-battery flag`() {
        val parsed = requireNotNull(parser.parse(byteArrayOf(0x25, 0x01)))
        assertEquals("Find My [Maintained]", parsed.deviceModel)
        assertEquals(0x25, parsed.statusFlags)
        assertNull(parsed.batteryLevelLeft)
    }

    @Test
    fun `maintained battery bits distinguish low and critical`() {
        val low = requireNotNull(parser.parse(byteArrayOf(0x84.toByte(), 0x01)))
        val critical = requireNotNull(parser.parse(byteArrayOf(0xC4.toByte(), 0x01)))
        assertTrue(low.deviceModel!!.contains("[Low Batt]"))
        assertTrue(critical.deviceModel!!.contains("[Critical Batt]"))
        assertNull(low.batteryLevelLeft)
        assertNull(critical.batteryLevelLeft)
    }

    @Test
    fun `battery state without maintained flag remains unknown`() {
        val parsed = requireNotNull(parser.parse(byteArrayOf(0x80.toByte(), 0x01)))
        assertEquals("Find My [Not Maintained]", parsed.deviceModel)
        assertFalse(parsed.deviceModel!!.contains("Batt"))
    }
}

package io.blueeye.core.decoders

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class AirTagBroadcastDecoderTest {
    private val decoder = AirTagBroadcastDecoder()

    @Test
    fun `status 0x25 is maintained with full battery`() {
        val input = input(0x25)
        assertTrue(decoder.supports(input))
        assertEquals("Bat: Full (St: 0x25)", decoder.decode(input).sensorStatus)
    }

    @Test
    fun `unmaintained flags cannot claim battery charge`() {
        assertEquals("Bat: Unknown (St: 0x80)", decoder.decode(input(0x80)).sensorStatus)
    }

    @Test
    fun `maintained low battery is derived from high bits`() {
        assertEquals("Bat: Low (St: 0x84)", decoder.decode(input(0x84)).sensorStatus)
    }

    private fun input(status: Int) = BleBeaconScanInput(
        mac = "",
        manufacturerRecords = mapOf(
            76 to byteArrayOf(0x12, 0x19, status.toByte()) + ByteArray(22),
        ),
        serviceUuids = emptyList(),
    )
}
